-- =============================================================================
-- seed.sql — dane startowe: kategorie HVAC, atrybuty, dostawa, grupy klientów,
-- marże, hurtownie, strony statyczne, produkty demo (z ofertami hurtowni mock).
-- Idempotentny (on conflict do nothing / update).
-- =============================================================================

-- --- Grupy klientów ---
on conflict (code) do nothing;

-- --- Hurtownie ---
on conflict (code) do nothing;

-- --- Reguły marż ---
select 'Marża globalna 18%', 'global', null, 18, 500, 0, true
where not exists (select 1 from public.margin_rules where scope = 'global');

-- --- Metody dostawy ---
on conflict (code) do nothing;

-- --- Kategorie (3 poziomy) ---
on conflict (slug) do nothing;

on conflict (slug) do nothing;

-- poziom 3: pompy ciepła powietrze-woda → monoblok / split
on conflict (slug) do nothing;

-- --- Definicje atrybutów (filtry techniczne) ---
on conflict (key) do nothing;

-- --- Strony statyczne ---
on conflict (slug) do nothing;

-- --- Marki ---
on conflict (slug) do nothing;

-- --- Produkty demo (30+) — mapowane do ofert hurtowni mock po EAN/SKU ---
on conflict (sku) do nothing;

-- --- Oferty hurtowni mock dla produktów demo (żeby ceny istniały bez uruchamiania syncu) ---
on conflict (supplier_id, supplier_sku) do update set purchase_net_cents = excluded.purchase_net_cents, stock = excluded.stock, lead_time_days = excluded.lead_time_days, product_id = excluded.product_id, fetched_at = now();

select o.supplier_id, o.supplier_sku, o.product_id, 'ean' from public.supplier_offers o where o.product_id is not null
on conflict (supplier_id, supplier_sku) do nothing;

-- --- Produkty powiązane (przykłady) ---
select p.id, r.id, 'accessory', row_number() over (partition by p.id)
from public.products p
join public.products r on r.sku in ('CU-SET-14-38', 'CU-14', 'CU-38', 'WSP-450', 'ASP-MINI-LIME', 'KAB-OMY-5x15')
where p.category_id = (select id from public.categories where slug = 'klimatyzatory-split')
on conflict do nothing;

select o.id, i.id, 'indoor_unit', 1
from public.products o join public.products i on i.sku = 'KAI-IN-WALL-26'
where o.sku in ('KAI-MULTI-2X', 'KAI-MULTI-3X')
on conflict do nothing;

-- --- Przeliczenie cen i stanów ---
select public.recalc_all_products();
