insert into public.static_pages (slug, title, content_html, published, position) values
  ('regulamin', 'Regulamin sklepu', '<h2>§1 Postanowienia ogólne</h2><p>Niniejszy regulamin określa zasady składania zamówień i zawierania umów sprzedaży w sklepie internetowym.</p><p><em>TODO(ustalić): pełna treść regulaminu od klienta (dane sprzedawcy, reklamacje, odstąpienie od umowy).</em></p>', true, 10),
  ('polityka-prywatnosci', 'Polityka prywatności', '<h2>Administrator danych</h2><p>Administratorem danych osobowych jest właściciel sklepu. Dane przetwarzane są w celu realizacji zamówień, prowadzenia konta klienta i obsługi reklamacji.</p><h2>Pliki cookies</h2><p>Sklep używa plików cookies niezbędnych do działania oraz, za zgodą, analitycznych i marketingowych. Zgodę można zmienić w każdej chwili w ustawieniach cookies.</p><p><em>TODO(ustalić): dane administratora i inspektora ochrony danych.</em></p>', true, 20),
  ('dostawa-i-platnosc', 'Dostawa i płatność', '<h2>Dostawa</h2><ul><li><strong>Kurier</strong> (DPD / InPost) — paczki do 30 kg, 1–2 dni robocze.</li><li><strong>Dostawa paletowa</strong> — klimatyzatory kasetonowe, kanałowe, pompy ciepła, rekuperatory oraz zamówienia powyżej 30 kg. 2–4 dni robocze.</li><li><strong>Odbiór osobisty</strong> — po potwierdzeniu dostępności towaru.</li></ul><h2>Płatność</h2><ul><li><strong>Przelew tradycyjny / proforma</strong> — numer konta i tytuł przelewu otrzymasz w e-mailu z potwierdzeniem zamówienia.</li><li><strong>Płatność odroczona 14 dni</strong> — dla zweryfikowanych klientów B2B.</li></ul><p><em>TODO(ustalić): płatności online (Przelewy24 / PayU / Tpay).</em></p>', true, 30),
  ('kontakt', 'Kontakt', '<p>Masz pytania o dobór urządzenia lub zamówienie? Napisz lub zadzwoń — doradzamy instalatorom i klientom indywidualnym.</p><p><em>TODO(ustalić): dane kontaktowe sklepu (telefon, e-mail, adres magazynu, godziny pracy).</em></p>', true, 40),
  ('o-nas', 'O nas', '<p>Jesteśmy sklepem specjalistycznym dla branży HVAC. Oferujemy klimatyzatory, pompy ciepła, systemy rekuperacji oraz pełne zaplecze montażowe i serwisowe, z dostawą paletową i obsługą B2B.</p><p><em>TODO(ustalić): treść od klienta.</em></p>', true, 50)
